<?php
declare(strict_types=1);require_once __DIR__.'/common.php';
if(($_SERVER['REQUEST_METHOD']??'')!=='POST')fb_out(false,'Only POST requests are allowed.',['code'=>'METHOD_NOT_ALLOWED'],405);$pdo=fb_pdo();$in=fb_in();$token=trim((string)($in['token']??''));$ticket=fb_access($pdo,$token);if(!$ticket)fb_out(false,'Invalid support link.',['code'=>'INVALID_TICKET_LINK'],404);$auth=fb_authorized($pdo,$ticket);if(!$auth['ok'])fb_out(false,'Verification required.',['code'=>'VERIFICATION_REQUIRED'],403);$u=$auth['user'];if($u){try{$pdo->prepare("UPDATE notifications SET is_read=1,read_at=CURRENT_TIMESTAMP WHERE user_id=:u AND reference_type='support_ticket' AND reference_id=:r")->execute([':u'=>(int)$u['user_id'],':r'=>(int)$ticket['ticket_id']]);}catch(Throwable $e){}}fb_out(true,'Support notifications marked read.');
